-- Check if order_behaviour REC_NODE directly links to traders somehow
SELECT ob."REC_NODE", tr2."rel_root" FROM order_behaviour ob 
JOIN trader_relationships tr2 ON ob."REC_NODE" = tr2."rel_root" LIMIT 5;

-- Maybe each trader has exactly one sentiment record through order_behaviour
-- Check: does every trader have an entry in order_behaviour?
SELECT COUNT(DISTINCT tr."TR_KEY") FROM traders tr;

-- How many order_behaviour entries match trade_records?
SELECT COUNT(DISTINCT ob."REC_NODE") FROM order_behaviour ob
JOIN trade_records tr ON ob."REC_NODE" = tr."REC_KEY";

-- How many traders have trades NOT linked to corporate events?
SELECT COUNT(DISTINCT tr."tr_anchor") FROM trade_records tr
WHERE tr."REC_KEY" NOT IN (SELECT "REC_EVT" FROM corporate_events);

-- Verify: all trade_records.REC_KEY match corporate_events.REC_EVT
SELECT COUNT(*) FROM trade_records tr
WHERE tr."REC_KEY" NOT IN (SELECT "REC_EVT" FROM corporate_events);

-- Maybe the link is traders -> trader_relationships -> order_behaviour
SELECT tr."rel_root", ob."REC_NODE" FROM trader_relationships tr 
JOIN order_behaviour ob ON tr."rel_root" = ob."REC_NODE" LIMIT 5;
